function ExpenseView({expenses,events,setModal,deleteExpense}){const now=new Date(),[month,setMonth]=useState(new Date(now.getFullYear(),now.getMonth(),1)),year=month.getFullYear(),m=month.getMonth(),key=year+'-'+String(m+1).padStart(2,'0'),rows=expenses.filter(x=>String(x.expense_date||'').startsWith(key)),em=new Map(events.map(e=>[e.id,e])),total=rows.reduce((n,x)=>n+Number(x.amount||0),0),eventTotal=rows.filter(x=>x.event_id).reduce((n,x)=>n+Number(x.amount||0),0),storeTotal=rows.filter(x=>!x.event_id).reduce((n,x)=>n+Number(x.amount||0),0),move=n=>setMonth(new Date(year,m+n,1));return <div className="listpage"><div className="sectionhead"><div><h2>経費</h2><p>1ヶ月ごとの店舗・イベント経費を管理</p></div><button className="primary" onClick={()=>setModal('expense')}>＋ 経費登録</button></div><div className="expense-month-nav"><button onClick={()=>move(-1)}>‹</button><h3>{year}年{m+1}月</h3><button onClick={()=>move(1)}>›</button><button onClick={()=>setMonth(new Date(now.getFullYear(),now.getMonth(),1))}>今月</button></div><div className="expense-month-total"><div><small>{year}年{m+1}月</small><span>月間経費合計</span></div><strong>¥{total.toLocaleString()}</strong></div><div className="moneycards expense-kpis"><div><small>イベント経費</small><b>¥{eventTotal.toLocaleString()}</b></div><div><small>店舗共通経費</small><b>¥{storeTotal.toLocaleString()}</b></div><div><small>登録件数</small><b>{rows.length}件</b></div></div><div className="expense-ledger"><div className="expense-row head"><b>日付</b><b>項目</b><b>金額</b><b>支払方法</b><b>対象イベント</b><b>取引先</b><b></b></div>{rows.length?rows.map(x=><div className="expense-row" key={x.id}><span>{Number(String(x.expense_date).slice(8,10))}日</span><b>{x.category}</b><strong>¥{Number(x.amount||0).toLocaleString()}</strong><span>{x.payment_method}</span><span>{x.event_id?(em.get(x.event_id)?.title||'イベント'):'店舗共通'}</span><span>{x.vendor||'—'}</span><button onClick={()=>deleteExpense(x.id)}>削除</button></div>):<div className="expense-empty">{year}年{m+1}月の経費はまだ登録されていません。</div>}</div></div>}


